67: // Dir returns the default root directory for Flipt configuration
68: func Dir() (string, error) {
69: 	configDir, err := os.UserConfigDir()
70: 	if err != nil {
71: 		return "", fmt.Errorf("getting user config dir: %w", err)
72: 	}
73: 
74: 	return filepath.Join(configDir, "flipt"), nil
75: }
