77: func Load(path string) (*Result, error) {
78: 	v := viper.New()
79: 	v.SetEnvPrefix(EnvPrefix)
80: 	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
81: 	v.AutomaticEnv()
82: 
83: 	var cfg *Config
84: 
85: 	if path == "" {
86: 		cfg = Default()
87: 	} else {
88: 		cfg = &Config{}
89: 		v.SetConfigFile(path)
90: 		if err := v.ReadInConfig(); err != nil {
91: 			return nil, fmt.Errorf("loading configuration: %w", err)
92: 		}
93: 	}
94: 
95: 	var (
96: 		result      = &Result{Config: cfg}
97: 		deprecators []deprecator
98: 		defaulters  []defaulter
99: 		validators  []validator
100: 	)
101: 
102: 	f := func(field any) {
103: 		// for-each deprecator implementing field we collect
104: 		// them up and return them to be run before unmarshalling and before setting defaults.
105: 		if deprecator, ok := field.(deprecator); ok {
106: 			deprecators = append(deprecators, deprecator)
107: 		}
108: 
109: 		// for-each defaulter implementing fields we invoke
110: 		// setting any defaults during this prepare stage
111: 		// on the supplied viper.
112: 		if defaulter, ok := field.(defaulter); ok {
113: 			defaulters = append(defaulters, defaulter)
114: 		}
115: 
116: 		// for-each validator implementing field we collect
117: 		// them up and return them to be validated after
118: 		// unmarshalling.
119: 		if validator, ok := field.(validator); ok {
120: 			validators = append(validators, validator)
121: 		}
122: 	}
123: 
124: 	// invoke the field visitor on the root config firsts
125: 	root := reflect.ValueOf(cfg).Interface()
126: 	f(root)
127: 
128: 	// these are reflected config top-level types for fields where
129: 	// they have been marked as experimental and their associated
130: 	// flag has enabled set to false.
131: 	var skippedTypes []reflect.Type
132: 
133: 	val := reflect.ValueOf(cfg).Elem()
134: 	for i := 0; i < val.NumField(); i++ {
135: 		// search for all expected env vars since Viper cannot
136: 		// infer when doing Unmarshal + AutomaticEnv.
137: 		// see: https://github.com/spf13/viper/issues/761
138: 		structField := val.Type().Field(i)
139: 		if exp := structField.Tag.Get("experiment"); exp != "" {
140: 			// TODO(georgemac): register target for skipping
141: 			if !v.GetBool(fmt.Sprintf("experimental.%s.enabled", exp)) {
142: 				skippedTypes = append(skippedTypes, structField.Type)
143: 			}
144: 		}
145: 
146: 		key := fieldKey(structField)
147: 		bindEnvVars(v, getFliptEnvs(), []string{key}, structField.Type)
148: 
149: 		field := val.Field(i).Addr().Interface()
150: 		f(field)
151: 	}
152: 
153: 	// run any deprecations checks
154: 	for _, deprecator := range deprecators {
155: 		warnings := deprecator.deprecations(v)
156: 		for _, warning := range warnings {
157: 			result.Warnings = append(result.Warnings, warning.Message())
158: 		}
159: 	}
160: 
161: 	// run any defaulters
162: 	for _, defaulter := range defaulters {
